    ex = {'path': str(example), 'sha256': sha(example), 'bytes': example.stat().st_size}
    small = [D / 'results/GEOM_UNC/field_model.json', D / 'results/DESIGN_implant/picks.jsonl', D / 'results/PROC_prep/runs/design_anatomy_h0.1.json', D / 'results/LANE_NEXT_J_CLINICIAN_PLACEMENTS/RAW_J3_CLEARANCES.jsonl', D / 'results/LANE_NEXT_N_CANAL_PROXIMITY/RAW_N2.jsonl', D / 'cells/geometry/tf2_io.py', D / 'results/LANE_NEXT_N_CANAL_PROXIMITY/DATASET_METADATA.json', Path(_release_expand('@DENTAL_CORPUS_ROOT@/geometry/STS-3D-Tooth/README.md'))]
    source = [{'path': str(p), 'sha256': sha(p), 'bytes': p.stat().st_size} for p in small]
